enum WGPUPolygonMode {
  WGPUPolygonMode_Fill(0),

  /// Polygons are drawn as line segments (wireframe).
  /// Requires @ref WGPUNativeFeature_PolygonModeLine.
  WGPUPolygonMode_Line(1),

  /// Polygons are drawn as points (vertices only).
  /// Requires @ref WGPUNativeFeature_PolygonModePoint.
  WGPUPolygonMode_Point(2);

  final int value;
  const WGPUPolygonMode(this.value);

  static WGPUPolygonMode fromValue(int value) => switch (value) {
    0 => WGPUPolygonMode_Fill,
    1 => WGPUPolygonMode_Line,
    2 => WGPUPolygonMode_Point,
    _ => throw ArgumentError('Unknown value for WGPUPolygonMode: $value'),
  };
}

