typedef WGPULogCallback = ffi.Pointer<ffi.NativeFunction<WGPULogCallbackFunction>>;

enum WGPUNativeTextureFormat {
  WGPUNativeTextureFormat_R16Unorm(196609),

  /// Red channel only. 16-bit signed integer per channel.
  /// [-32767, 32767] converted to/from float [-1, 1] in shader.
  /// Requires @ref WGPUNativeFeature_TextureFormat16bitNorm.
  WGPUNativeTextureFormat_R16Snorm(196610),

  /// Red and green channels. 16-bit unsigned integer per channel.
  /// [0, 65535] converted to/from float [0, 1] in shader.
  /// Requires @ref WGPUNativeFeature_TextureFormat16bitNorm.
  WGPUNativeTextureFormat_Rg16Unorm(196611),

  /// Red and green channels. 16-bit signed integer per channel.
  /// [-32767, 32767] converted to/from float [-1, 1] in shader.
  /// Requires @ref WGPUNativeFeature_TextureFormat16bitNorm.
  WGPUNativeTextureFormat_Rg16Snorm(196612),

  /// Red, green, blue, and alpha channels. 16-bit unsigned integer per channel.
  /// [0, 65535] converted to/from float [0, 1] in shader.
  /// Requires @ref WGPUNativeFeature_TextureFormat16bitNorm.
  WGPUNativeTextureFormat_Rgba16Unorm(196613),

  /// Red, green, blue, and alpha channels. 16-bit signed integer per channel.
  /// [-32767, 32767] converted to/from float [-1, 1] in shader.
  /// Requires @ref WGPUNativeFeature_TextureFormat16bitNorm.
  WGPUNativeTextureFormat_Rgba16Snorm(196614),

  /// YUV 4:2:0 chroma subsampled format (NV12).
  /// Plane 0 contains R8Unorm luminance (Y), Plane 1 contains Rg8Unorm
  /// chrominance (UV) at half width and half height.
  /// Requires @ref WGPUNativeFeature_TextureFormatNv12.
  WGPUNativeTextureFormat_NV12(196615),

  /// YUV 4:2:0 with 10 bits used from 16-bit channels (P010).
  /// Plane 0 contains R16Unorm luminance (Y), Plane 1 contains Rg16Unorm
  /// chrominance (UV) at half width and half height.
  WGPUNativeTextureFormat_P010(196616);

  final int value;
  const WGPUNativeTextureFormat(this.value);

  static WGPUNativeTextureFormat fromValue(int value) => switch (value) {
    196609 => WGPUNativeTextureFormat_R16Unorm,
    196610 => WGPUNativeTextureFormat_R16Snorm,
    196611 => WGPUNativeTextureFormat_Rg16Unorm,
    196612 => WGPUNativeTextureFormat_Rg16Snorm,
    196613 => WGPUNativeTextureFormat_Rgba16Unorm,
    196614 => WGPUNativeTextureFormat_Rgba16Snorm,
    196615 => WGPUNativeTextureFormat_NV12,
    196616 => WGPUNativeTextureFormat_P010,
    _ => throw ArgumentError('Unknown value for WGPUNativeTextureFormat: $value'),
  };
}

